def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    y = float(obs['rig']['trailer_rear'][1])
    st = obs.get('status', '')
    if abs(h) > 60 or st in ('JACKKNIFED', 'PINNED'):
        return (0.0, 0.6, 180.0)
    hd = max(-15.0, min(15.0, -12.0 * (y + 0.2)))
    steer = 2.5 * (h - hd)
    steer = max(-45.0, min(45.0, steer))
    spd = -0.6 if abs(h) < 15.0 else -0.35
    return (steer, spd, 180.0)

