PHASE = 'rev'
FWD_D = 0.0

def control(obs):
    global PHASE, FWD_D
    dt = float(obs.get('dt', 0.1) or 0.1)
    st = obs.get('status', '')
    v = float(obs.get('motion', {}).get('v_mps', 0.0))
    h = float(obs.get('hitch_deg', 0.0))
    y = float(obs['rig']['trailer_rear'][1])
    if st in ('PINNED', 'JACKKNIFED'):
        PHASE = 'pull'
        FWD_D = 0.0
        return (0.0, 0.5, 180.0)
    if PHASE == 'pull':
        if v > 0:
            FWD_D += v * dt
        if FWD_D < 1.0:
            return (0.0, 0.5, 180.0)
        PHASE = 'rev'
    hd = max(-12.0, min(12.0, -12.0 * (y - 0.1)))
    steer = 2.5 * (h - hd)
    steer = max(-45.0, min(45.0, steer))
    spd = -0.5 if abs(h) < 15.0 else -0.35
    return (steer, spd, 180.0)

