    st = obs.get('status', '')
    v = float(obs.get('motion', {}).get('v_mps', 0.0))
    dt = float(obs.get('dt', 0.1) or 0.1)
    h = float(obs.get('hitch_deg', 0.0))
    y = float(obs['rig']['trailer_rear'][1])
    if st in ('PINNED', 'JACKKNIFED'):
        PH = 'pull'
        FD = 0.0
    if PH == 'pull':
        if v > 0:
            FD += v * dt
        if FD < 0.8:
            return (0.0, 0.4, 180.0)
        PH = 'rev'
    if abs(h) > 60:
        PH = 'pull'
        FD = 0.0
        return (0.0, 0.4, 180.0)
    hd = max(-8.0, min(8.0, 15.0 * (0.12 - y)))
    steer = max(-45.0, min(45.0, 2.5 * (h - hd)))
    return (steer, -0.2, 180.0)

